def public_summary(rows):
    totals = {'completed': 0, 'failed': 0}
    for row in rows:
        state = row.get('state')
        count = row.get('count')
        if state not in totals:
            raise ValueError('Unsupported report state')
        if type(count) is not int or count < 0:
            raise ValueError('Count must be a nonnegative integer')
        totals[state] += count
